#!/usr/bin/env python3
"""Static site generator for Waste Tracking Finder (D-010). Run: python3 tools/build.py
Re-runnable: drop a new data/dataset.csv (Sam's format, see data/README) and rebuild. Outputs HTML into the repo root."""
import csv,html,json,os,re,shutil,datetime
ROOT=os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SITE=os.environ.get("WTF_SITE","https://wastetrackingfinder.co.uk")  # placeholder until domain bought; github.io URL can be passed via env
PREVIEW=os.environ.get("WTF_PREVIEW","0")=="1"   # live since 20 Oct 2026; WTF_PREVIEW=1 for a noindex preview build
EMAIL=os.environ.get("WTF_EMAIL","hello@wastetrackingfinder.co.uk")  # Google Workspace alias domain (Matthew, 19 Oct 2026)
UPDATED="2026-10-26"   # data/guide quotes last checked against GOV.UK; drives dateModified, sitemap lastmod, guide "last checked"
LEGAL_UPDATED="2026-10-29"   # privacy and terms: change only when their text changes
ENTITY="Matthew Snow trading as Sno Automations"
ADDRESS="The Bristol Office, 2nd Floor, 5 High Street, Westbury-on-Trym, Bristol BS9 3BY"
ICO="ZC276141"
LIST="https://www.gov.uk/government/publications/report-receipt-of-waste-choose-a-software-provider"
RRW="https://www.gov.uk/guidance/report-receipt-of-waste"
CHECK="https://www.gov.uk/guidance/digital-waste-tracking-check-if-you-need-to-report-the-waste-you-receive"
DEV="https://www.gov.uk/government/publications/digital-waste-tracking-service/digital-waste-tracking-service"
OGL="https://www.nationalarchives.gov.uk/doc/open-government-licence/version/3/"
E=html.escape
rows=list(csv.DictReader(open(f"{ROOT}/data/dataset.csv",encoding="utf-8")))
m=re.search(r"list updated (\d{4}-\d\d-\d\d)",rows[0]["source_date"]);LIST_DATE=datetime.date.fromisoformat(m.group(1))
def dtxt(d):return f"{d.day} {d.strftime('%b %Y')}"
TYPES=[("waste management (general)","waste-management-general","Waste management (general)"),("skip hire","skip-hire","Skip hire"),("scrap metal / vehicle dismantling","scrapyards-metal","Scrap metal and vehicle dismantling"),("weighbridge / weighing","weighbridges","Weighbridges and weighing"),("agri / compost / AD","agri-compost-ad","Agriculture, compost and AD"),("ERP / business suite","erp-business-suites","ERP and business suites"),("haulage / transport management","haulage-transport","Haulage and transport management"),("field service / job management","field-service","Field service and job management")]
TMAP={k:(s,l) for k,s,l in TYPES};OTHER=("other-not-yet-categorised","Other / not yet categorised")
def slugify(s):return re.sub(r"-+","-",re.sub(r"[^a-z0-9]+","-",s.lower().replace("&","and"))).strip("-")
used=set();P=[]
for r in rows:
    s=slugify(re.sub(r"\(exempt for certain PAT scenarios\)","",r["product"],flags=re.I)) or slugify(r["provider"])
    if s in used:s=slugify(r["product"]+"-"+r["provider"])
    used.add(s)
    url=r["url"] if r["url"] and r["url_basis"].startswith("hand-checked") else ""
    price=r["public_price"] if r["public_price"] and r["price_note"].startswith(("hand-checked","read from pricing page")) else ""
    pd=re.search(r"(\d{1,2} \w{3} \d{4})",r["price_note"]);
    t=TMAP.get(r["type_category"]);ts,tl=(t if t else OTHER)
    P.append(dict(name=r["product"],prov=r["provider"],slug=s,url=url,price=price,pricedate=pd.group(1) if pd else "",pat=r["pat_exemption"]=="yes",tslug=ts,tlabel=tl,typed=bool(t),basis=r["type_basis"]))
P.sort(key=lambda p:p["name"].lower())
N=len(P);NPROV=len({p["prov"] for p in P})
# Sponsors: data/sponsors.json [{"slug":..,"blurb":..,"until":"YYYY-MM-DD"}]. Shown in a separate labelled box; never changes list order.
SP=json.load(open(f"{ROOT}/data/sponsors.json")) if os.path.exists(f"{ROOT}/data/sponsors.json") else []
pages=[]
NAV=[("software/","All software"),("what-is-digital-waste-tracking/","Guides"),("penalties/","Penalties"),("about-methodology/","Methodology"),("sponsor/","List your software")]
def q(text,src,label):return f"<blockquote>“{E(text)}”<cite class='small'>Source: <a href='{src}'>{E(label)}</a> (GOV.UK)</cite></blockquote>"
def contact():return f"<a href='mailto:{EMAIL}'>{EMAIL}</a>" if EMAIL else "<span class='tbc'>[contact email to be confirmed]</span>"
def page(path,title,desc,body,ld=None,kind="WebPage",sitemap=True,notfound=False,noindex=False):
    depth=path.count("/");pre="/" if notfound else "../"*depth
    url=f"{SITE}/{path}"
    g=[{"@type":"Organization","@id":SITE+"/#org","name":"Sno Automations","alternateName":"Waste Tracking Finder","url":SITE+"/","founder":{"@type":"Person","name":"Matthew Snow"},"address":{"@type":"PostalAddress","streetAddress":"The Bristol Office, 2nd Floor, 5 High Street, Westbury-on-Trym","addressLocality":"Bristol","postalCode":"BS9 3BY","addressCountry":"GB"},"description":f"Waste Tracking Finder is run by {ENTITY}, a UK sole trader."},{"@type":"WebSite","@id":SITE+"/#site","name":"Waste Tracking Finder","url":SITE+"/","inLanguage":"en-GB","publisher":{"@id":SITE+"/#org"}}]
    if not notfound:g.append({"@type":kind,"name":title,"url":url,"dateModified":(LEGAL_UPDATED if path in ("privacy/","terms/") else UPDATED),"isPartOf":{"@id":SITE+"/#site"}})
    lds=[{"@context":"https://schema.org","@graph":g}]+([ld] if ld else [])
    nav="".join(f"<li><a href='{pre}{h}'{' aria-current=\"page\"' if h==path else ''}>{t}</a></li>" for h,t in NAV)
    robots="<meta name='robots' content='noindex'>" if (PREVIEW or notfound or noindex) else ""
    canon="" if notfound else f"<link rel='canonical' href='{url}'>"
    doc=f"""<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)}</title><meta name="description" content="{E(desc)}">{robots}{canon}<meta property="og:title" content="{E(title)}"><meta property="og:description" content="{E(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="{url}"><link rel="icon" href="{pre}assets/favicon.svg" type="image/svg+xml"><link rel="icon" href="{pre}assets/favicon-32.png" sizes="32x32" type="image/png"><link rel="apple-touch-icon" href="{pre}assets/apple-touch-icon.png"><link rel="stylesheet" href="{pre}assets/style.css"><link rel="stylesheet" href="{pre}assets/wtf.css">{''.join(f'<script type="application/ld+json">{json.dumps(l,ensure_ascii=False)}</script>' for l in lds)}</head><body>
<a class="skip" href="#main">Skip to content</a>{'<div class="previewbar">Preview build: not published. Not yet checked by QA.</div>' if PREVIEW else ''}
<header class="site"><div class="wrap nav"><a class="brand" href="{pre or './'}">Waste Tracking <em>Finder</em></a><button class="menu-btn" aria-expanded="false" aria-controls="navlist" aria-label="Menu">Menu</button><ul id="navlist">{nav}</ul></div></header>
<main id="main">{body}</main>
<footer><div class="wrap"><div class="cols"><div><a class="brand" href="{pre or './'}">Waste Tracking <em>Finder</em></a><p>An independent guide to the software on GOV.UK's list of software providers for the Report receipt of waste service. Not run by, affiliated with or endorsed by Defra, the Environment Agency or any UK government body. Not legal advice.</p><p>Run by {ENTITY}. Business address: {ADDRESS}. ICO registration {ICO}. Contact: {contact()}</p><p class="small">Contains public sector information licensed under the <a href="{OGL}">Open Government Licence v3.0</a>. Product and provider names from GOV.UK's <a href="{LIST}">Report receipt of waste: choose a software provider</a>, list updated {dtxt(LIST_DATE)}.</p></div>
<div><p><a href="{pre}software/">All software</a><br><a href="{pre}what-is-digital-waste-tracking/">What is digital waste tracking?</a><br><a href="{pre}report-receipt-of-waste/">Report receipt of waste</a><br><a href="{pre}scotland-ni-1-january-2027/">Scotland and NI: 1 Jan 2027</a><br><a href="{pre}carriers-brokers-dealers-2027/">Carriers, brokers, dealers</a><br><a href="{pre}penalties/">Penalties</a></p></div>
<div><p><a href="{pre}about-methodology/">Methodology</a><br><a href="{pre}sponsor/">List your software</a><br><a href="{pre}newsletter/">Newsletter</a><br><a href="{pre}disclaimer/">Disclaimer</a><br><a href="{pre}privacy/">Privacy</a><br><a href="{pre}terms/">Terms</a><br><a href="{pre}contact/">Contact</a></p></div></div></div></footer>
<script src="{pre}assets/wtf.js" defer></script><script data-goatcounter="https://wastetrackingfinder.goatcounter.com/count" async src="/assets/count.js"></script></body></html>"""
    doc=re.sub(r"<a href='(https?://[^']+)'>",lambda m:f"<a href='{m.group(1)}' target='_blank' rel='noopener'>",doc)
    doc=re.sub(r'<a href="(https?://[^"]+)">',lambda m:f'<a href="{m.group(1)}" target="_blank" rel="noopener">',doc)
    out=f"{ROOT}/404.html" if notfound else f"{ROOT}/{path}index.html"
    os.makedirs(os.path.dirname(out),exist_ok=True);open(out,"w",encoding="utf-8").write(doc)
    if sitemap and not notfound:pages.append(path)
def card(p,pre):
    tags=[f"<a class='tag' href='{pre}{p['tslug']}/'>{E(p['tlabel'])}</a>"]
    if p["pat"]:tags.append("<span class='tag pat'>Exempt for certain PAT scenarios (per GOV.UK)</span>")
    price=f"<p class='price'>{E(p['price'])} <span class='small'>· price checked {p['pricedate']}</span></p>" if p["price"] else "<p class='small'>No public price checked yet.</p>"
    site=f"<a href='{p['url']}' rel='nofollow noopener'>Vendor website</a>" if p["url"] else f"<a href='{LIST}'>See GOV.UK's list</a>"
    return f"<article class='card prod' data-type='{p['tslug']}' data-pat='{int(p['pat'])}' data-price='{int(bool(p['price']))}' data-q='{E((p['name']+' '+p['prov']).lower())}'><h3><a href='{pre}software/{p['slug']}/'>{E(p['name'])}</a></h3><p class='small'>by {E(p['prov'])}</p><p>{''.join(tags)}</p>{price}<p class='small'>{site}</p></article>"
def sponsor_box(pre,tslug=None):
    live=[s for s in SP if s.get("until","")>=UPDATED and (tslug is None or s.get("type") in (None,tslug))]
    bs={p["slug"]:p for p in P}
    items="".join(f"<div class='card featured'><span class='badge'>Sponsored</span><h3>{E(bs[s['slug']]['name'])}</h3><p>{E(s.get('blurb',''))}</p><p><a href='{bs[s['slug']]['url'] or LIST}' rel='sponsored noopener'>Visit</a></p></div>" for s in live if s["slug"] in bs)
    return f"<aside class='sponsored' aria-label='Sponsored listings'><p class='small'>Sponsored listings are paid for, always labelled, and shown here only. They never change the order of the list below.</p>{items}</aside>" if items else ""
TYPED=sum(p["typed"] for p in P);PRICED=sum(bool(p["price"]) for p in P);URLS=sum(bool(p["url"]) for p in P);PATN=sum(p["pat"] for p in P)
def finder(pre,subset,filters=True):
    tcount={};[tcount.__setitem__(p["tslug"],tcount.get(p["tslug"],0)+1) for p in subset]
    opts="".join(f"<label class='chk'><input type='checkbox' name='type' value='{s}'> {E(l)} ({tcount[s]})</label>" for k,s,l in TYPES if s in tcount)
    if OTHER[0] in tcount:opts+=f"<p class='small'>{tcount[OTHER[0]]} products are <a href='{pre}{OTHER[0]}/'>not yet categorised</a> and are hidden while a type filter is ticked.</p>"
    side=f"""<div class='side' id='filters'><h2>Filter</h2><div class='grp'><strong>Site type</strong>{opts}</div><div class='grp'><label class='chk'><input type='checkbox' name='pat' value='1'> Exempt for certain PAT scenarios</label><label class='chk'><input type='checkbox' name='price' value='1'> Public price shown</label></div></div>""" if filters else ""
    return f"""<div class='finder{'' if filters else ' nofilter'}'>{side}<div><div class='searchbar'><label style='flex:1'><span class='vh'>Search by product or provider</span><input id='q' type='search' placeholder='Search {len(subset)} products or providers' autocomplete='off'></label>{'<button class="btn ghost filter-toggle" type="button" aria-controls="filters" aria-expanded="false">Filters</button>' if filters else ''}</div><p class='resbar small' role='status' aria-live='polite'><span id='count'>{len(subset)}</span>&nbsp;of {len(subset)} shown, A–Z. Order is never changed by payment.</p><div class='grid' id='list'>{''.join(card(p,pre) for p in subset)}</div><p id='none' class='small' hidden>No products match. Clear a filter or search again.</p></div></div>"""
def itemlist(subset,name):return {"@context":"https://schema.org","@type":"ItemList","name":name,"numberOfItems":len(subset),"itemListElement":[{"@type":"ListItem","position":i+1,"url":f"{SITE}/software/{p['slug']}/","name":p["name"]} for i,p in enumerate(subset)]}
def hero(eyebrow,h1,lede):return f"<section class='wrap narrow'><span class='eyebrow'>{eyebrow}</span><h1>{h1}</h1><p class='lede'>{lede}</p></section>"
INTRO=q("Permitted or licenced waste receiving sites in England and Wales must report their waste digitally, using the report receipt of waste service. This came into effect on 1 October 2026. In Northern Ireland and Scotland this comes into effect on 1 January 2027.",LIST,"Report receipt of waste: choose a software provider")
# Home
page("","Digital waste tracking software finder (UK) | Waste Tracking Finder",f"Search all {N} products on GOV.UK's list of software providers for the Report receipt of waste service, filtered by site type. Independent, free, A–Z.",
 hero("Independent · Free · A–Z",f"Find <em>digital waste tracking</em> software",f"Every one of the {N} products from {NPROV} providers on GOV.UK's list of software providers for the Report receipt of waste service, with site type, PAT exemptions and checked prices. List updated by GOV.UK {dtxt(LIST_DATE)}.")+
 f"<section class='wrap narrow'>{INTRO}<p class='small'>GOV.UK's list gives only product and provider names. We add site type ({TYPED} of {N} so far), vendor websites we have hand-checked ({URLS}) and public prices read on vendors' own sites ({PRICED}). See <a href='about-methodology/'>how we build the list</a>.</p></section>"+
 f"<section class='wrap'>{sponsor_box('')}{finder('',P)}</section>"+
 "<section class='wrap narrow'><h2>Get the waste tracking countdown</h2><p>Short emails when GOV.UK's list changes and before key dates.</p><div class='kit'><script async data-uid=\"a32b61c615\" src=\"https://mtd-finder.kit.com/a32b61c615/index.js\"></script></div><p class='small'>Double opt-in. Unsubscribe any time. See our <a href='privacy/'>privacy policy</a>.</p></section>",ld=itemlist(P,"Software on GOV.UK's list for Report receipt of waste"))
page("software/","All digital waste tracking software, A–Z | Waste Tracking Finder",f"All {N} products on GOV.UK's Report receipt of waste software list, A–Z.",
 hero("A–Z",f"All {N} products, A to Z",f"In the same order for everyone. Each links to its own page. List updated by GOV.UK {dtxt(LIST_DATE)}.")+f"<section class='wrap'>{finder('../',P,False)}</section>",ld=itemlist(P,"All software A–Z"),kind="CollectionPage")
for k,s,l in TYPES+[(None,)+OTHER]:
    sub=[p for p in P if p["tslug"]==s]
    if not sub:continue
    note="These products haven't been given a site type yet. They're checked by hand, so the group shrinks over time." if k is None else "Site type is our own reading of each product's name or website, not a GOV.UK category. It may be refined."
    page(f"{s}/",f"{l} software for digital waste tracking | Waste Tracking Finder",f"{len(sub)} products on GOV.UK's Report receipt of waste software list that we class as {l.lower()}.",
     hero("Site type",E(l),f"{len(sub)} of the {N} products on GOV.UK's list. {note}")+f"<section class='wrap'>{sponsor_box('../',s)}{finder('../',sub,False)}</section>",ld=itemlist(sub,l),kind="CollectionPage")
for p in P:
    pre="../../"
    rows_=[("Product (as on GOV.UK)",E(p["name"])),("Provider (as on GOV.UK)",E(p["prov"])),("On GOV.UK's list",f"Yes, list updated {dtxt(LIST_DATE)}: <a href='{LIST}'>see GOV.UK</a>"),("PAT exemption","GOV.UK marks it “exempt for certain PAT scenarios”. Ask the provider which scenarios." if p["pat"] else "None shown on GOV.UK's list"),("Site type (our reading)",f"<a href='{pre}{p['tslug']}/'>{E(p['tlabel'])}</a>"),("Public price",f"{E(p['price'])} (price checked {p['pricedate']}, as shown on the vendor's site, VAT as stated)" if p["price"] else "Not checked yet. Ask the provider."),("Website",f"<a href='{p['url']}' rel='nofollow noopener'>{E(p['url'])}</a> (hand-checked 19 Oct 2026; may be the provider's company site)" if p["url"] else f"Not found yet. Find the provider on <a href='{LIST}'>GOV.UK's list</a>.")]
    tbl="".join(f"<tr><th scope='row'>{a}</th><td>{b}</td></tr>" for a,b in rows_)
    ld={"@context":"https://schema.org","@type":"SoftwareApplication","name":p["name"],"applicationCategory":"BusinessApplication","publisher":{"@type":"Organization","name":p["prov"]},**({"url":p["url"]} if p["url"] else {})}
    page(f"software/{p['slug']}/",f"{p['name']} by {p['prov']}: digital waste tracking software | Waste Tracking Finder",f"{p['name']} by {p['prov']} is on GOV.UK's list of software providers for the Report receipt of waste service. Site type, PAT exemption and price.",
     f"<section class='wrap narrow'><p class='small'><a href='{pre}software/'>All software</a> › {E(p['name'])}</p><span class='eyebrow'>On GOV.UK's list of software providers</span><h1>{E(p['name'])}</h1><p class='lede'>by {E(p['prov'])}</p><table class='facts'>{tbl}</table><p class='small'>Being on GOV.UK's list means the provider is listed for the Report receipt of waste service. It is not an endorsement by Defra or by us. Check fit, price and support with the provider before you buy.</p><p><a class='btn ghost' href='{pre}{p['tslug']}/'>More {E(p['tlabel'].lower())} software</a></p></section>",ld=ld)
def guide(path,title,desc,eyebrow,h1,body,label=""):
    page(path,title,desc,f"<section class='wrap narrow'><span class='eyebrow'>{eyebrow}</span>{label}<h1>{h1}</h1><p class='small'>Last checked against GOV.UK {dtxt(datetime.date.fromisoformat(UPDATED))}. Not legal advice; check your duties with your regulator.</p>{body}<p><a class='btn' href='{'../'*path.count('/')}'>Find software</a></p></section>",kind="Article")
guide("what-is-digital-waste-tracking/","What is digital waste tracking? Dates and who it applies to | Waste Tracking Finder","Plain-English guide to UK digital waste tracking: who must report the waste they receive, when, and how, quoted from GOV.UK.","Guide","What is <em>digital waste tracking</em>?",
 "<h2>Who must report now</h2>"+q("If you are licensed or permitted to receive controlled waste, you will need to enter details of every load you receive using the ‘Report receipt of waste’ service.",CHECK,"Digital waste tracking: check if you need to report the waste you receive")+
 q("If you receive waste in England or Wales, you must use the service from 1 October 2026.",CHECK,"Digital waste tracking: check if you need to report the waste you receive")+
 "<h2>How fast</h2>"+q("You must submit records within 2 working days (excluding weekends and bank holidays), starting on the day after you receive the waste.",CHECK,"Digital waste tracking: check if you need to report the waste you receive")+
 "<h2>Paper notes carry on for now</h2>"+q("This means you must continue to complete waste transfer notes, Annex VII forms and hazardous waste consignment notes (where required).",CHECK,"Digital waste tracking: check if you need to report the waste you receive")+
 "<h2>Timeline</h2><ul><li>1 Oct 2026: receiving sites in England and Wales (in force).</li><li>1 Jan 2027: receiving sites in Scotland and Northern Ireland. <a href='../scotland-ni-1-january-2027/'>Guide</a></li><li>31 Jan 2027: first £26 service charge due. <a href='../report-receipt-of-waste/'>Guide</a></li><li>Oct 2027: carriers, brokers and dealers, <strong>is a plan, not a legal duty yet</strong>. <a href='../carriers-brokers-dealers-2027/'>Guide</a></li></ul>")
guide("report-receipt-of-waste/","Report receipt of waste: API or spreadsheet, and the £26 charge | Waste Tracking Finder","How to send data to the Report receipt of waste service by software (API) or spreadsheet, and the £26 a year charge due 31 January 2027.","Guide","Report receipt of waste: <em>API or spreadsheet</em>",
 q("You do not have to choose one method – you can submit your data using a combination of the API and spreadsheet.",RRW,"Report receipt of waste")+
 "<h2>Software (API)</h2>"+q("If you want to use the API , your organisation must have waste specific software. Your software provider will need to connect it to Defra ’s Receipt of Waste API .".replace(" ,",",").replace(" ’","’").replace(" .","."),RRW,"Report receipt of waste")+f"<p>That's the list this site covers: <a href='../'>all {N} products</a>.</p>"+
 "<h2>Spreadsheet</h2>"+q("You cannot use your own spreadsheet or make format changes to Defra’s version.",RRW,"Report receipt of waste")+
 "<h2>The charge</h2>"+q("The service costs £26 per year for each organisation on your account. The charge covers all waste-receiving sites that organisation has. The first payment is due by 31 January 2027.",RRW,"Report receipt of waste"))
guide("scotland-ni-1-january-2027/","Digital waste tracking in Scotland and Northern Ireland: 1 January 2027 | Waste Tracking Finder","Receiving sites in Scotland and Northern Ireland must report waste digitally from 1 January 2027, per GOV.UK.","Deadline · 1 Jan 2027","Scotland and Northern Ireland: <em>1 January 2027</em>",
 INTRO+q("January 2027 – service mandatory for receiving site operators in Northern Ireland and Scotland",DEV,"Developing the digital waste tracking service")+"<p>For questions about your duties, GOV.UK points to SEPA in Scotland and DAERA in Northern Ireland (source: <a href='"+RRW+"'>Report receipt of waste</a>).</p>")
guide("carriers-brokers-dealers-2027/","Digital waste tracking for carriers, brokers and dealers: Oct 2027 is a plan, not a legal duty yet | Waste Tracking Finder","Defra plans to make digital waste tracking mandatory for waste collectors from October 2027. This is a plan, not a legal duty yet.","Oct 2027 · is a plan, not a legal duty yet","Carriers, brokers and dealers: <em>October 2027</em>",
 "<div class='warn'><strong>Oct 2027 is a plan, not a legal duty yet.</strong> This date comes from a Defra policy paper, and it could change.</div>"+
 q("from autumn 2026 – digital waste tracking service to be available to an invited group of waste collectors in increasing numbers (private beta phase)",DEV,"Developing the digital waste tracking service")+q("from spring 2027 – digital waste tracking service to be available publicly for all waste collectors (public beta phase)",DEV,"Developing the digital waste tracking service")+q("from October 2027 – digital waste tracking service mandatory for waste collectors",DEV,"Developing the digital waste tracking service")+
 "<p>On the spreadsheet route:</p>"+q("We currently expect it to remain in place until at least October 2027.",DEV,"Developing the digital waste tracking service"),label="<span class='tag warn-tag'>Is a plan, not a legal duty yet</span>")
guide("penalties/","Digital waste tracking penalties: £1,000 fixed and unlimited variable | Waste Tracking Finder","The penalties for not following the digital waste tracking rules in England and Wales, quoted from GOV.UK.","Guide","Digital waste tracking <em>penalties</em>",
 q("You will be committing an offence if you do not comply with the rules. This includes rules on deadlines, outages, written records, correcting errors, digital exclusion and making accurate records using the service.",CHECK,"Digital waste tracking: check if you need to report the waste you receive")+
 "<p>GOV.UK lists these possible outcomes: “compliance notice”, “enforcement cost recovery notice”, “variable monetary penalty of an unlimited amount”, “fixed monetary penalty of £1,000” and “criminal prosecution and, if convicted, an unlimited fine” (<a href='"+CHECK+"'>source</a>).</p>"+
 q("You could also face up to 2 years in prison if you knowingly make false or misleading statements or records to regulators.",CHECK,"Digital waste tracking: check if you need to report the waste you receive")+
 q("If you receive a notice of intention to serve a monetary penalty, you have 28 days to submit a written objection to your regulator.",CHECK,"Digital waste tracking: check if you need to report the waste you receive"))
def simple(path,title,desc,eyebrow,h1,body):page(path,title,desc,f"<section class='wrap narrow prose'><span class='eyebrow'>{eyebrow}</span><h1>{h1}</h1>{body}</section>")
simple("about-methodology/","How we build the list: methodology | Waste Tracking Finder","How Waste Tracking Finder sources, orders and checks its listings.","About","How we build <em>the list</em>",
 f"<p>Waste Tracking Finder is independent. It's run by {ENTITY} and is not run by, affiliated with or endorsed by Defra or any regulator. We never describe a product as “approved by Defra”; we say it is on GOV.UK's list of software providers.</p><h2>Source</h2><p>Every product and provider comes from GOV.UK's <a href='{LIST}'>Report receipt of waste: choose a software provider</a>, list updated {dtxt(LIST_DATE)} ({N} products, {NPROV} providers). Names are shown exactly as GOV.UK writes them. If GOV.UK removes a product, we remove it.</p><h2>What we add</h2><ul><li><strong>Site type</strong> ({TYPED} of {N}): our reading of the product's name or website. {N-TYPED} are “Other / not yet categorised” and don't appear in any type filter.</li><li><strong>Websites</strong> ({URLS} of {N}): found by hand and checked on 19 Oct 2026. Some are the provider's company site. Where we haven't found one, we link to GOV.UK's list rather than guess.</li><li><strong>Prices</strong> ({PRICED} of {N}): only prices we read on the vendor's own site, as shown (VAT as stated), each with the date we checked it.</li><li><strong>PAT exemptions</strong> ({PATN}): copied from GOV.UK's list. We don't know which scenarios apply.</li></ul><h2>Order and sponsorship</h2><p>Lists are A–Z by product name, the same for everyone. Sponsored listings are labelled “Sponsored”, shown in a separate box, use rel=\"sponsored\", and never change the order or contents of any list or guide. If we ever use affiliate links, we'll say so next to the link.</p><h2>Errors</h2><p>Spotted a mistake? Contact {contact()}.</p>")
simple("sponsor/","List your software: sponsored listings | Waste Tracking Finder","Sponsored listings for providers on GOV.UK's Report receipt of waste software list.","For providers","List your <em>software</em>",
 f"<p>Every product on GOV.UK's list already has a free page here, A–Z. A sponsored listing adds a labelled box at the top of the finder and your type page.</p><ul><li>Always labelled “Sponsored”, with rel=\"sponsored\".</li><li>Never changes the order of any list or our guides.</li><li>Only for products on GOV.UK's list.</li></ul><h2>Price</h2><p><strong>£29 a month</strong> for each of the first 5 sponsored listings, then <strong>£49 a month</strong>. The first five sponsors keep the £29 a month price for as long as their listing stays live. Billed monthly through Stripe; cancel any time. Every sponsored listing is labelled “Sponsored” and never changes the order of any list.</p><p><a class='btn' href='https://buy.stripe.com/eVq8wQcq0ct82et6dta3u01' rel='nofollow'>Book a founding listing, £29 a month</a></p><p class='small'>Payment is taken securely by Stripe. Your listing goes live once we've checked the product is on GOV.UK's list.</p><p>To ask about a listing or correct your free page, contact {contact()}.</p>")
simple("newsletter/","Waste tracking countdown newsletter | Waste Tracking Finder","Get GOV.UK list changes and deadline reminders for digital waste tracking.","Newsletter","Waste tracking <em>countdown</em>",
 "<p>Short emails when GOV.UK's software list changes and before key dates: 1 January 2027 (Scotland and Northern Ireland) and 31 January 2027 (first £26 charge).</p><div class='kit'><script async data-uid=\"a32b61c615\" src=\"https://mtd-finder.kit.com/a32b61c615/index.js\"></script></div><p class='small'>Double opt-in: you'll get an email to confirm. Unsubscribe any time. See our <a href='../privacy/'>privacy policy</a>.</p>")
page("newsletter/confirmed/","You're confirmed | Waste Tracking Finder","Your Waste Tracking Finder newsletter subscription is confirmed.","<section class='wrap narrow prose'><span class='eyebrow'>Newsletter</span><h1>You're <em>confirmed</em></h1><p>Thanks for confirming your email. You're now on the Waste Tracking Finder newsletter. We'll email you when GOV.UK's software list changes and before key dates: 1 January 2027 (Scotland and Northern Ireland) and 31 January 2027 (first £26 charge).</p><p>You can unsubscribe at any time with the link in every email. See our <a href='../../privacy/'>privacy policy</a>.</p><p><a class='btn' href='../../'>Find waste tracking software</a></p></section>",sitemap=False,noindex=True)
simple("disclaimer/","Disclaimer | Waste Tracking Finder","Disclaimer for Waste Tracking Finder.","Legal","Disclaimer",f"<p>Waste Tracking Finder is an independent information site, not legal or compliance advice. It is not run by, affiliated with or endorsed by Defra, the Environment Agency, Natural Resources Wales, SEPA, DAERA or any government body. Product details come from GOV.UK's public list and vendors' own websites and can change. Always check with GOV.UK, your regulator or the provider before relying on them.</p>")
simple("contact/","Contact | Waste Tracking Finder","Contact Waste Tracking Finder.","Contact","Contact",f"<p>{ENTITY}<br>Business address: {ADDRESS}</p><p>Email: {contact()}</p><p>For questions about your legal duties, contact your regulator; GOV.UK lists them on <a href='{RRW}'>Report receipt of waste</a>.</p>")
simple("privacy/","Privacy policy | Waste Tracking Finder",f"How Waste Tracking Finder, run by {ENTITY}, handles personal data under UK GDPR.","Legal","Privacy policy",
 f"<p class='small'>Last updated {LEGAL_UPDATED}.</p><h2>Who we are</h2><p>Waste Tracking Finder is run by {ENTITY}, a UK sole trader. Business address: {ADDRESS}. For UK data protection law (the UK GDPR and the Data Protection Act 2018), Matthew Snow is the data controller. Contact: {contact()}. Matthew Snow is registered with the Information Commissioner's Office (ICO), registration number {ICO}. You can check this on the <a href='https://ico.org.uk/ESDWebPages/Search'>ICO register</a>.</p><h2>Browsing the site</h2><p>We don't use advertising or tracking cookies, and this site sets no cookies of its own. The search and filters run in your browser. The site is hosted by GitHub Pages (GitHub, Inc.), which processes technical information such as your IP address to deliver and secure the site. See <a href='https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement'>GitHub's privacy statement</a>. Our lawful basis is legitimate interests in running a secure, working website.</p><h2>Businesses we list</h2><p>We list products and providers from GOV.UK's public list. A few providers may be sole traders, so a listing can include a person's trading name. We use this public business information on the basis of legitimate interests in helping waste businesses find software. To correct or query your listing, contact us.</p><h2>If you email us</h2><p>We use your email address and message to reply, on the basis of legitimate interests, and keep correspondence normally no more than two years.</p><h2>Sponsors and payments</h2><p>If you buy a sponsored listing, payment is taken by Stripe, which collects your card details directly. We never see your full card number. We use your name, business name, email, billing address and payment status to provide the listing and keep accounts (lawful basis: contract and legal obligation). Payment and accounting records are kept for at least 5 years after the 31 January deadline for the tax year they relate to, which is GOV.UK's guidance for sole traders (<a href='https://www.gov.uk/self-employed-records/how-long-to-keep-your-records'>GOV.UK</a>). See <a href='https://stripe.com/gb/privacy'>Stripe's privacy policy</a>.</p><h2>Business contacts we approach</h2><p>Now and then we email software providers that appear on <a href='{LIST}'>GOV.UK's public list of software providers</a> for the Report receipt of waste service, to tell them about the site, check their listing details or discuss a sponsored listing. We use only business contact details they publish themselves on their own websites, such as a role inbox or contact form, on the basis of legitimate interests in telling relevant organisations about the site. We don't record the names of individuals. We keep a record of who we contacted and when, and if you ask us not to contact you again, we add you to a suppression list and won't. Contact: {contact()}.</p><h2>Your rights</h2><p>You can ask to access, correct, delete or restrict your data, object to processing, or withdraw consent at any time. Contact {contact()}. You can also complain to the <a href='https://ico.org.uk/make-a-complaint/'>ICO</a>.</p><h2>Newsletter</h2><p>If you sign up, we use your email address to send the newsletter, on the basis of your consent. That means short emails when GOV.UK's software list changes and before key dates. Sign-up uses double opt-in, so you confirm by email first.</p><p>Sign-ups and our mailing list are managed by Kit (Kit, Inc.), a US-based email service that processes the data on our behalf (see its <a href='https://kit.com/dpa'>data processing addendum</a>). Transfers of UK personal data to the US are protected by the UK Extension to the EU-US Data Privacy Framework and/or the UK International Data Transfer Addendum to the EU standard contractual clauses. Kit may record whether you open or click our emails. Every email has an unsubscribe link, and you can also email {contact()} to unsubscribe. When you unsubscribe, we delete your address, or keep only a suppression record so we don't email you again. See <a href='https://kit.com/privacy'>Kit's privacy policy</a>.</p><h2>Visitor statistics</h2><p>We use GoatCounter to count visits. It sets no cookies and doesn't store IP addresses or build profiles of visitors. It tells us totals such as which pages are read and which sites sent visitors. GoatCounter is run from Ireland and stores its data in Finland and Germany. Our lawful basis is legitimate interests in understanding how the site is used. See <a href='https://www.goatcounter.com/help/privacy'>GoatCounter's privacy notes</a>.</p>")
simple("terms/","Terms of use and sponsorship terms | Waste Tracking Finder",f"Terms of use and sponsored listing terms for Waste Tracking Finder, run by {ENTITY}.","Legal","Terms",
 f"<p class='small'>Last updated {LEGAL_UPDATED}.</p><h2>About these terms</h2><p>These terms apply to your use of Waste Tracking Finder, run by {ENTITY}, a UK sole trader (“we”, “us”). Business address: {ADDRESS}. Contact: {contact()}. By using the site you accept these terms.</p><h2>Using the site</h2><p>Waste Tracking Finder is an independent information site. We're not affiliated with or endorsed by Defra or any regulator, and nothing here is legal or compliance advice. Details come from GOV.UK's public list and vendors and can change, so confirm with GOV.UK or the vendor before you rely on them. See our <a href='../disclaimer/'>disclaimer</a>. You may share the content for personal, non-commercial use with a link back. GOV.UK material is used under the Open Government Licence v3.0.</p><h2>Our liability</h2><p>We provide the site “as is” and don't guarantee it will be accurate, complete or always available. As far as the law allows, we aren't liable for any loss arising from your use of, or reliance on, the site or any site we link to. Nothing in these terms limits liability for death or personal injury caused by negligence, for fraud, or for anything else that can't be limited by law.</p><h2>Sponsorship terms</h2><p><strong>The listing.</strong> A sponsored listing is a clearly labelled “Sponsored” slot. Listings are only for products on GOV.UK's list. We may edit listing text for accuracy, clarity and tone.</p><p><strong>Editorial independence.</strong> Sponsorship never changes the order of any list, our guides or our editorial judgement, and we always label paid placements.</p><p><strong>Price and billing.</strong> £29 a month for each of the first 5 sponsored listings, then £49 a month. The first five sponsors keep the £29 a month price for as long as their listing stays live. Billed monthly in advance through Stripe until you cancel. We don't currently charge VAT. We'll give at least 30 days' notice of any price change.</p><p><strong>Cancelling.</strong> You can cancel at any time; cancellation takes effect at the end of the paid period. We don't refund partial months, except where the law requires it.</p><p><strong>Refusing or removing listings.</strong> We may refuse any listing, and remove one if the product leaves GOV.UK's list, the information is misleading, or it breaks these terms or the law. If we remove a listing for any reason other than your breach, we'll refund the unused part of the current month.</p><p><strong>Liability for sponsors.</strong> We don't guarantee any level of traffic, clicks or sales. As far as the law allows, our total liability to a sponsor is limited to the fees paid in the three months before the claim.</p><h2>Changes and law</h2><p>We may update these terms and will show the date at the top. These terms are governed by the law of England and Wales.</p>")
page("404/","Page not found | Waste Tracking Finder","Page not found.",hero("404","Page <em>not found</em>","That page doesn't exist. Try the <a href='/'>software finder</a>."),notfound=True)
open(f"{ROOT}/sitemap.xml","w").write('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+"".join(f"<url><loc>{SITE}/{p}</loc><lastmod>{UPDATED}</lastmod></url>" for p in pages)+"</urlset>\n")
open(f"{ROOT}/robots.txt","w").write(("User-agent: *\nDisallow: /\n" if PREVIEW else "User-agent: *\nAllow: /\n")+f"Sitemap: {SITE}/sitemap.xml\n")
print(f"built {len(pages)} sitemap pages + 404; products {N}, typed {TYPED}, urls {URLS}, prices {PRICED}, PAT {PATN}")
